window.kbPageData["views/entry/k-ef1b2f97e9a838ee"] = {"key":"entry/k-ef1b2f97e9a838ee","state":{"route":"entry/k-ef1b2f97e9a838ee"},"node":{"id":"k-ef1b2f97e9a838ee","mode":"k","title":"持之以恒推进全面从严治党遵循的原则“七个坚持”：","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["二十届五中全会"],"资料类别":["时政"]},"directorySummary":"1.持之以恒推进全面从严治党遵循的原则“七个坚持”：\n坚持服务使命任务，就要围绕全面建成社会主义现代化强国、实现第二个百年奋斗目\n标，以更高标准、更实举措推进全面从严治党，确保党始终成为中国特色社会主义事业的\n坚强领导核心；\n坚持以党的政治建设为统领，就要保证全党服从中央，坚持党中央权威和集中统一领…","sources":[{"id":"2c75834f1125c963","label":"持之以恒推进全面从严治党遵循的原则“七个坚持”：","topic":"二十届五中全会","category":"时政","text":"1.持之以恒推进全面从严治党遵循的原则“七个坚持”：\n坚持服务使命任务，就要围绕全面建成社会主义现代化强国、实现第二个百年奋斗目\n标，以更高标准、更实举措推进全面从严治党，确保党始终成为中国特色社会主义事业的\n坚强领导核心；\n坚持以党的政治建设为统领，就要保证全党服从中央，坚持党中央权威和集中统一领\n导；\n坚持全面从严，就要坚持严的基调不动摇，真管真严、敢管敢严、长管长严；\n坚持问题导向，就要奔着问题去、盯着问题改，把党的建设面临的突出问题整治好、\n解决好；\n坚持守正创新，就要守好本和源、根和魂，与时俱进、开拓进取，积极识变应变求变；\n坚持以上率下，就要一级带一级，一级做给一级看，各级领导干部自觉起示范带头作\n用；\n坚持依规治党，就要健全科学完备、有效管用的制度体系，全方位织密制度的笼子。\n“七个坚持”相互贯通、有机统一，既是认识论，又是方法论，体现了对马克思主义政\n党建设规律的深刻把握。","source":{"doc":"41195a191a57c1c36332","first":12,"last":12,"page":12,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-ef1b2f97e9a838ee":[]}};
